// ==UserScript==
// @name         Torn Item Market - Shop Sell Price Highlighter
// @namespace    https://github.com/tulpn/torn-item-market-highlighter
// @version      0.5.0
// @description  Highlights Item Market listings whose price is below what a city shop (Big Al's etc.) pays for the item.
// @author       ares313377
// @homepageURL  https://www.torn-tracker.com/scripts
// @license      Torn Scripts No-Modification License - https://github.com/tulpn/torn-item-market-highlighter/blob/main/LICENSE
// @match        https://www.torn.com/page.php?sid=ItemMarket*
// @run-at       document-idle
// @grant        none
// ==/UserScript==

/*
 * How it works
 *  1. Shop sell prices are baked into this file (SHOP_SELL_PRICES below). Run build-prices.ps1
 *     to (re)generate that table. The script itself makes no network requests and needs no API key.
 *  2. Watches the Item Market page for listing rows / item tiles. Each one is identified by its
 *     item image (/images/items/<id>/...), and the nearest "$1,234" text is treated as the price.
 *  3. If price < shop sell price, the row gets a coloured border, a dot and a short profit label
 *     next to the price. The colour depends on the profit tier. Hovering the price shows details.
 *     Decoration is attribute-only (CSS pseudo-elements); no nodes are inserted into Torn's rows.
 *  4. A gear button (bottom right) opens a settings panel: tiers, colours, profit-vs-margin mode,
 *     inline label, listing totals, hide-unprofitable and the count badge.
 *  5. Settings persist in Torn PDA's PDA_storage when available, otherwise in localStorage.
 */

(function () {
  'use strict';

  // ---------------------------------------------------------------- defaults
  // These are the defaults. Users change them in the settings panel (gear button on the page);
  // saved settings override whatever is written here.
  const CONFIG = {
    mode: 'abs',               // 'abs' = profit per unit in $, 'pct' = margin in % of market price
    tiersAbs: [                // used in 'abs' mode: min = profit per unit ($)
      { min: 50000, color: '#2ecc71', label: 'green' },
      { min: 10000, color: '#f1c40f', label: 'yellow' },
      { min: 1000,  color: '#e74c3c', label: 'red' },
      { min: 1,     color: '#3b1ee0', label: 'blue' },
    ],
    tiersPct: [                // used in 'pct' mode: min = margin (%)
      { min: 100, color: '#2ecc71', label: 'green' },
      { min: 50,  color: '#f1c40f', label: 'yellow' },
      { min: 20,  color: '#e74c3c', label: 'red' },
      { min: 1,   color: '#3b1ee0', label: 'blue' },
    ],
    inlineLabel: true,         // show "+12.5k" next to the price
    showTotal: true,           // include profit x quantity when a quantity is visible
    hideUnprofitable: false,   // collapse listings that are not profitable
    showSummary: true,         // count badge on the gear button
    debug: false,
  };

  // ---------------------------------------------------------------- data
  // Generated by build-prices.ps1 - { itemId: shopSellPrice }. Items shops won't buy are omitted.
  // @@SHOP_PRICES_START
  // generated 2026-10-16 - 577 items
  const SHOP_PRICES_GENERATED = '2026-10-16';
  const SHOP_SELL_PRICES = {"1":50,"2":130,"3":250,"4":500,"5":750,"6":1000,"7":1500,"8":3000,"9":5400,"10":11500,"11":53000,"12":270,"13":370,"14":650,"15":1300,"16":1850,"17":3500,"18":7500,"19":16000,"20":37000,"21":900000,"22":1400,"23":3300,"24":3800,"25":6600,"26":10000,"27":12500,"28":21400,"29":36000,"30":75000,"31":670000,"32":1700,"33":7500,"34":33000,"35":15,"36":20,"37":16,"38":20,"39":22,"40":20,"41":25,"42":25,"43":20,"44":20,"45":65,"46":32,"47":35,"48":40,"49":60000,"50":750000,"51":55,"52":125,"53":260,"54":2700,"55":35,"56":95,"57":185,"58":20,"59":70,"60":225,"61":300,"62":150,"63":1250000,"64":295,"65":250,"66":10000,"67":7500,"68":3750,"69":500,"70":4500,"71":10000,"72":75000,"73":200000,"77":29000,"78":40000,"79":55000,"80":43000,"81":80000,"82":50000,"83":69000,"84":59000,"85":150000,"86":21000,"87":13000,"88":15000,"89":23000,"90":9000,"91":7600,"92":5600,"93":17000,"94":7000,"95":25000,"96":2,"97":3,"99":300,"103":100,"104":200,"105":350,"107":325000,"108":600000,"110":750,"111":5000,"129":250,"145":500,"147":40,"151":50,"154":400,"159":15,"172":70,"173":1200,"174":9000,"175":4250,"176":3100,"177":55000,"178":4750,"180":5,"181":3100,"182":10,"183":100,"184":300,"186":15,"187":10,"189":900,"190":1800,"209":250,"210":100,"215":25,"217":75000,"218":750,"219":200000,"220":7000,"221":6500,"222":10000,"223":4000000,"224":2000,"225":50000,"226":15000,"227":400,"228":6500,"229":11000,"230":200,"231":35000,"232":55000,"233":40000,"234":2000,"235":4000,"236":40000,"237":80000,"238":700,"239":400,"240":17000000,"241":10000,"242":15000,"243":400,"244":2000,"245":300,"246":300,"247":13000,"248":70000,"249":5000,"250":40000,"251":60000,"252":7000,"253":200,"254":25000,"255":2500000,"256":10000,"257":30000,"258":8000,"259":350,"260":250,"261":25,"262":300,"263":400,"264":500,"265":1800,"266":150,"267":4000,"268":750,"269":300,"270":30,"271":350,"272":700,"273":300,"274":300,"275":10000,"276":4000,"277":300,"278":7000,"279":35000,"280":300,"281":300,"282":1500,"283":23500000,"294":30,"305":5,"306":5,"307":5,"308":5,"309":5,"310":10,"332":2700000,"333":4500000,"334":9000000,"336":500000000,"358":70000,"359":10,"361":700000,"372":3,"377":20,"378":15,"379":20,"383":400,"384":11000,"385":4000,"391":80000,"392":600,"393":10,"394":3,"395":300000,"397":6000000,"398":3750000,"399":15000000,"400":150000,"401":100,"402":15000,"403":10,"404":300,"405":1,"406":30000,"407":1750,"408":15000,"409":7500,"410":15000,"411":13000,"412":3000,"413":22500,"414":2000,"415":25000,"416":1,"417":15,"418":7500,"419":1000000,"420":2000000,"421":5000000,"426":60,"427":175,"429":10,"430":300000,"431":500,"432":10,"433":300,"434":3000,"436":4000,"437":5,"438":10000,"439":300,"440":150,"453":8500000,"454":3500000,"455":12000000,"456":12000000,"457":12000000,"458":15000000,"463":675000,"464":225000,"465":975000,"483":500,"484":500,"485":500,"486":500,"487":500,"488":500,"489":500,"490":500,"494":8000,"495":7500,"496":8000,"497":7500,"498":6500,"499":8000,"500":7000,"501":5500,"502":9000,"503":20000,"504":11000,"505":8500,"506":7300,"508":30000,"509":21000,"510":27000,"511":22000,"512":19000,"513":27000,"514":60000,"515":28000,"516":32000,"517":2100000,"518":810000,"520":1075000,"521":3600000,"522":4700000,"523":1900000,"524":170000,"527":20,"528":25,"529":75,"534":10,"535":15,"536":35,"537":35,"538":9000000,"540":500,"557":15,"559":100,"560":4,"562":25,"581":20,"586":55,"587":45,"598":75,"601":60,"603":300,"606":80,"607":30,"608":60,"609":120,"610":70,"612":350000,"613":200000,"614":800000,"615":40000000,"616":2,"617":3000,"618":300,"619":1000,"620":500,"621":15000,"622":7500,"623":4000,"624":6000,"625":20000,"626":3000,"634":5,"635":200,"636":15,"637":35,"639":35000,"640":320000,"641":71000,"643":11500,"645":58000,"646":4200,"647":900,"648":850,"649":720,"650":600,"651":2600000,"652":2450000,"653":1920000,"654":1870000,"697":1,"698":15,"700":27,"701":4,"702":5,"703":17,"707":1,"731":11250,"742":150,"790":4,"791":7,"814":450000,"856":5,"857":5,"858":5,"859":5,"860":5,"861":5,"862":5,"863":5,"864":5,"868":1,"882":1,"883":1,"885":50,"887":5,"888":75,"889":30,"890":250,"892":5,"894":200,"895":30,"896":2000,"897":1,"898":10000,"899":25000,"900":5000,"901":5,"902":15,"903":10,"904":75,"905":100,"906":10,"907":10,"909":1,"956":45,"957":10,"1039":40,"1084":75,"1085":10,"1086":5000,"1087":5,"1089":1,"1091":45,"1092":15,"1094":2,"1095":3,"1096":125,"1123":80,"1143":2,"1152":10000000,"1153":8000000,"1154":12000000,"1155":10000000,"1156":10000000,"1157":8000000,"1189":125,"1198":20,"1199":8500,"1200":350,"1201":5,"1202":30,"1203":495,"1204":80000,"1205":60,"1206":35,"1207":15,"1208":10,"1209":3750,"1210":65,"1211":8000,"1212":20,"1213":25,"1214":20,"1215":50,"1216":220,"1217":15,"1219":200,"1220":75,"1221":30,"1222":200,"1224":75,"1225":3750,"1226":200,"1227":20,"1228":20,"1230":300,"1231":2150,"1232":400,"1234":65,"1235":200,"1236":600,"1237":25,"1238":2700,"1240":2000,"1241":200,"1242":100,"1243":22000,"1244":5500,"1245":45000,"1246":210,"1247":25000,"1248":25,"1249":55,"1250":1500,"1251":75500,"1252":100,"1253":6500,"1254":90,"1255":800,"1256":4000,"1257":1250,"1258":2000,"1259":4325,"1260":30000,"1261":20,"1262":500,"1263":300,"1264":700,"1265":150,"1266":20,"1267":35,"1268":50,"1269":30,"1271":95,"1272":5,"1273":5,"1274":10,"1275":20,"1276":20,"1277":35,"1278":4000,"1279":1900,"1280":700,"1281":2200,"1282":400,"1283":200,"1284":150,"1285":15,"1286":20,"1287":30,"1289":50,"1291":5,"1300":255,"1301":180,"1303":20,"1306":175,"1313":265,"1314":6500,"1315":45250,"1316":20,"1317":125,"1318":10,"1319":35,"1320":65,"1321":15,"1322":25,"1327":3500,"1328":10,"1329":45,"1330":60,"1331":375,"1332":40,"1333":15,"1334":10,"1335":6500,"1336":62500,"1337":50000,"1338":10,"1339":180000,"1340":35,"1341":3250,"1342":122500,"1343":580000,"1345":75000,"1349":95000,"1350":230000,"1361":15,"1362":25,"1379":195000,"1381":105000,"1382":15,"1429":15,"1430":2400,"1431":80000,"1465":2250000,"1466":3,"1482":90000,"1483":9000,"1484":35000,"1485":66000,"1486":98000,"1489":27000,"1490":16000,"1491":20000,"1492":70000,"1493":40000,"1494":205000,"1495":430000,"1496":150000,"1497":240000,"1498":70000,"1508":70000000,"1554":130000000,"1555":30000000,"1556":70000000};
  // @@SHOP_PRICES_END

  const TAG = '[TM-ShopHighlight]';
  const STORE_KEY = 'tmsh_settings';
  const MAX_LABEL = 12;
  const PRICE_RE = /\$\s?([\d,]+)/;
  const IMG_ID_RE = /\/images\/items\/(\d+)\//;
  const HEX_RE = /^#[0-9a-f]{6}$/i;
  // "x 12", "12x", "qty 12", "quantity: 12" - the digits must not be part of a price
  const QTY_RE = /(?:^|[^\w$])x\s?(\d[\d,]*)|(?:^|[^$\d,])(\d[\d,]*)\s?x(?!\w)|\b(?:qty|quantity)\s*:?\s*(\d[\d,]*)/i;

  const log = (...a) => CONFIG.debug && console.log(TAG, ...a);

  // ---------------------------------------------------------------- storage
  // Torn PDA injects PDA_storage: async, per-script, SQLite-backed, survives cache clears.
  // Browsers fall back to localStorage. Both paths store one JSON-serialisable object.
  const storage = (() => {
    const pda = typeof PDA_storage !== 'undefined' && PDA_storage && typeof PDA_storage.get === 'function'
      ? PDA_storage : null;
    return {
      backend: pda ? 'PDA_storage' : 'localStorage',
      async load() {
        try {
          if (pda) return await pda.get(STORE_KEY, null);
          const raw = localStorage.getItem(STORE_KEY);
          return raw ? JSON.parse(raw) : null;
        } catch (err) {
          console.warn(TAG, 'could not load settings', err);
          return null;
        }
      },
      async save(obj) {
        try {
          if (pda) await pda.set(STORE_KEY, obj);
          else localStorage.setItem(STORE_KEY, JSON.stringify(obj));
          return true;
        } catch (err) {
          console.warn(TAG, 'could not save settings', err && err.code, err);
          return false;
        }
      },
      async clear() {
        try {
          if (pda) await pda.delete(STORE_KEY);
          else localStorage.removeItem(STORE_KEY);
        } catch (err) {
          console.warn(TAG, 'could not clear settings', err);
        }
      },
    };
  })();

  // ---------------------------------------------------------------- settings
  // Everything read from storage is treated as untrusted and normalised field by field.
  const bool = (v, d) => (typeof v === 'boolean' ? v : d);
  const tierKey = (mode) => (mode === 'pct' ? 'tiersPct' : 'tiersAbs');

  function sanitizeTiers(list, fallback) {
    const clean = Array.isArray(list)
      ? list
        .map((t) => ({
          min: Number(t && t.min),
          color: t && HEX_RE.test(String(t.color)) ? String(t.color).toLowerCase() : '#ffffff',
          label: String((t && t.label) || '').slice(0, MAX_LABEL),
        }))
        .filter((t) => Number.isFinite(t.min) && t.min >= 0)
      : [];
    return clean.length ? clean : fallback.map((t) => ({ ...t }));
  }

  function normalizeSettings(raw) {
    const s = raw && typeof raw === 'object' ? raw : {};
    return {
      mode: s.mode === 'pct' ? 'pct' : 'abs',
      tiersAbs: sanitizeTiers(s.tiersAbs, CONFIG.tiersAbs),
      tiersPct: sanitizeTiers(s.tiersPct, CONFIG.tiersPct),
      inlineLabel: bool(s.inlineLabel, CONFIG.inlineLabel),
      showTotal: bool(s.showTotal, CONFIG.showTotal),
      hideUnprofitable: bool(s.hideUnprofitable, CONFIG.hideUnprofitable),
      showSummary: bool(s.showSummary, CONFIG.showSummary),
    };
  }

  let S = normalizeSettings(null);
  let REV = 0; // bumped whenever settings change so every row is re-evaluated

  const activeTiers = () => [...S[tierKey(S.mode)]].sort((a, b) => b.min - a.min);

  // ---------------------------------------------------------------- styles
  const style = document.createElement('style');
  style.textContent = `
    .tmsh-good { outline: 2px solid var(--tmsh-color) !important; outline-offset: -2px; border-radius: 4px; }
    .tmsh-hide { display: none !important; }
    [data-tmsh-dot]::before {
      content: ''; display: inline-block; width: 9px; height: 9px; border-radius: 50%;
      background: var(--tmsh-color); box-shadow: 0 0 4px var(--tmsh-color);
      margin-left: 6px; vertical-align: middle;
    }
    [data-tmsh-label]::after {
      content: attr(data-tmsh-label); color: var(--tmsh-color); font-weight: 700;
      margin-left: 4px; font-size: .9em; white-space: nowrap;
    }
    #tmsh-fab {
      position: fixed; right: 12px; bottom: 84px; z-index: 99998;
      width: 38px; height: 38px; border-radius: 50%;
      background: #222; color: #fff; border: 1px solid #555;
      box-shadow: 0 2px 8px rgba(0,0,0,.4); cursor: pointer;
      display: flex; align-items: center; justify-content: center; font-size: 18px; line-height: 1;
    }
    #tmsh-fab .tmsh-count {
      position: absolute; top: -6px; right: -6px; min-width: 18px; height: 18px; padding: 0 5px;
      border-radius: 9px; background: #2ecc71; color: #000;
      font: 700 11px/18px sans-serif; text-align: center;
    }
    #tmsh-fab .tmsh-count[hidden] { display: none; }
    #tmsh-panel {
      position: fixed; right: 12px; bottom: 130px; z-index: 99999;
      width: min(370px, calc(100vw - 24px)); max-height: min(80vh, 620px); overflow: auto;
      background: #1e1e1e; color: #eee; border: 1px solid #555; border-radius: 8px; padding: 12px;
      font: 13px/1.4 sans-serif; box-shadow: 0 4px 16px rgba(0,0,0,.5); box-sizing: border-box;
    }
    #tmsh-panel[hidden] { display: none; }
    #tmsh-panel h3 { margin: 0 0 8px; font-size: 14px; }
    #tmsh-panel table { width: 100%; border-collapse: collapse; margin: 6px 0; }
    #tmsh-panel td, #tmsh-panel th { padding: 3px 2px; text-align: left; font-weight: normal; }
    #tmsh-panel th { color: #aaa; font-size: 11px; }
    #tmsh-panel input, #tmsh-panel select {
      background: #2b2b2b; color: #eee; border: 1px solid #555; border-radius: 3px;
      padding: 2px 4px; font: inherit; box-sizing: border-box;
    }
    #tmsh-panel input[type=number] { width: 90px; }
    #tmsh-panel input[type=text] { width: 80px; }
    #tmsh-panel input[type=color] { width: 36px; height: 24px; padding: 0; }
    #tmsh-panel input[type=checkbox] { width: auto; margin-right: 6px; }
    #tmsh-panel button {
      background: #333; color: #eee; border: 1px solid #666; border-radius: 4px;
      padding: 4px 9px; cursor: pointer; font: inherit;
    }
    #tmsh-panel button.tmsh-primary { background: #2ecc71; color: #000; border-color: #2ecc71; font-weight: 700; }
    #tmsh-panel label.tmsh-check { display: block; margin: 4px 0; }
    #tmsh-panel .tmsh-row { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-top: 10px; }
    #tmsh-panel .tmsh-muted { color: #999; font-size: 11px; margin-top: 10px; }
    #tmsh-panel .tmsh-status { color: #e74c3c; font-size: 12px; margin-top: 6px; min-height: 1em; }
  `;
  document.head.appendChild(style);

  // ---------------------------------------------------------------- helpers
  const fmt = (n) => '$' + Math.round(n).toLocaleString('en-US');
  const trimZeros = (s) => (s.includes('.') ? s.replace(/\.?0+$/, '') : s);
  function short(n) {
    const a = Math.abs(n);
    if (a >= 1e9) return trimZeros((n / 1e9).toFixed(2)) + 'b';
    if (a >= 1e6) return trimZeros((n / 1e6).toFixed(2)) + 'm';
    if (a >= 1e3) return trimZeros((n / 1e3).toFixed(1)) + 'k';
    return String(Math.round(n));
  }

  function parsePrice(text) {
    const m = PRICE_RE.exec(text);
    return m ? Number(m[1].replace(/,/g, '')) : null;
  }

  function parseQty(text) {
    const m = QTY_RE.exec(text);
    if (!m) return 1;
    const n = Number((m[1] || m[2] || m[3] || '').replace(/,/g, ''));
    return Number.isFinite(n) && n > 0 ? n : 1;
  }

  // Tiny DOM builder so the panel is built without innerHTML. Text children are always text nodes.
  function el(tag, attrs, ...children) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (v == null || v === false) continue;
      if (k === 'checked' || k === 'selected' || k === 'hidden') node[k] = v;
      else if (k === 'value') node.value = String(v);
      else node.setAttribute(k, v === true ? '' : String(v));
    }
    for (const c of children) {
      node.append(typeof c === 'string' || typeof c === 'number' ? document.createTextNode(String(c)) : c);
    }
    return node;
  }

  // Images that are UI chrome rather than listings: dropdown options, filter togglers, buttons.
  function isChrome(img) {
    return !!img.closest(
      '[role="listbox"], [role="option"], button, [class*="filtersWrapper"], [class*="dropdown"], [class*="Dropdown"], #tmsh-panel'
    );
  }

  // Walk up from the item image until we hit an element whose text contains a price.
  // Give up if that ancestor holds more than one item image - then it's a list, not a listing.
  function findRow(img) {
    let node = img.parentElement;
    for (let depth = 0; node && depth < 8; depth++, node = node.parentElement) {
      if (!PRICE_RE.test(node.textContent)) continue;
      if (node.querySelectorAll('img[src*="/images/items/"]').length > 1) return null;
      return node;
    }
    return null;
  }

  // Deepest element inside `row` whose own text includes the price (dot + label attach here).
  function findPriceEl(row) {
    const walker = document.createTreeWalker(row, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (PRICE_RE.test(node.nodeValue)) return node.parentElement;
    }
    return row;
  }

  // ---------------------------------------------------------------- row decoration
  function clearRow(row) {
    row.classList.remove('tmsh-good', 'tmsh-hide');
    row.style.removeProperty('--tmsh-color');
    for (const node of row.querySelectorAll('[data-tmsh-dot]')) {
      node.removeAttribute('data-tmsh-dot');
      node.removeAttribute('data-tmsh-label');
      node.removeAttribute('title');
    }
  }

  function evaluate(price, shopPrice, tiers) {
    const profit = shopPrice - price;
    const margin = (profit / price) * 100;
    const metric = S.mode === 'pct' ? margin : profit;
    const tier = shopPrice > 0 && profit > 0 ? tiers.find((t) => metric >= t.min) || null : null;
    return { profit, margin, tier };
  }

  function decorate(row, img, id, price, shopPrice, qty, tiers) {
    clearRow(row);
    const { profit, margin, tier } = evaluate(price, shopPrice, tiers);

    if (!tier) {
      if (S.hideUnprofitable) row.classList.add('tmsh-hide');
      return;
    }

    row.classList.add('tmsh-good');
    row.style.setProperty('--tmsh-color', tier.color);

    const name = img.getAttribute('alt') || `Item ${id}`;
    const hasQty = S.showTotal && qty > 1;
    const lines = [
      name + (tier.label ? ` (${tier.label})` : ''),
      `Market ${fmt(price)} | Shop pays ${fmt(shopPrice)}`,
      `Profit ${fmt(profit)} per unit (${margin.toFixed(1)}%)`,
    ];
    if (hasQty) lines.push(`Listing: ${qty} x = ${fmt(profit * qty)} total`);

    const priceEl = findPriceEl(row);
    priceEl.setAttribute('data-tmsh-dot', '');
    priceEl.title = lines.join('\n');
    if (S.inlineLabel) {
      let label = S.mode === 'pct' ? `+${Math.round(margin)}%` : `+${short(profit)}`;
      if (hasQty) label += ` (${short(profit * qty)})`;
      priceEl.setAttribute('data-tmsh-label', label);
    }
    log('highlight', name, price, '<', shopPrice, tier.label);
  }

  // ---------------------------------------------------------------- scan
  function scan() {
    const tiers = activeTiers();
    for (const img of document.querySelectorAll('img[src*="/images/items/"]')) {
      const m = IMG_ID_RE.exec(img.getAttribute('src'));
      if (!m || isChrome(img)) continue;

      const row = findRow(img);
      if (!row) continue;

      const text = row.textContent;
      const price = parsePrice(text);
      if (!price) continue; // null or 0

      const id = m[1];
      const shopPrice = SHOP_SELL_PRICES[id] || 0;
      const qty = parseQty(text);

      const sig = `${id}:${price}:${qty}:${REV}`;
      if (row.dataset.tmshSig === sig) continue;
      row.dataset.tmshSig = sig;

      decorate(row, img, id, price, shopPrice, qty, tiers);
    }
    updateBadge();
  }

  function rescan() {
    REV++;
    scan();
  }

  function updateBadge() {
    const badge = document.querySelector('#tmsh-fab .tmsh-count');
    if (!badge) return;
    const n = document.querySelectorAll('.tmsh-good').length;
    badge.textContent = String(n);
    badge.hidden = !(S.showSummary && n > 0);
  }

  // ---------------------------------------------------------------- settings UI
  let panel = null;

  function buildUI() {
    const fab = el('button', { id: 'tmsh-fab', type: 'button', title: 'Shop Sell Price Highlighter - settings' },
      '⚙',
      el('span', { class: 'tmsh-count', hidden: true }, '0'),
    );
    panel = el('div', { id: 'tmsh-panel', hidden: true });
    document.body.append(fab, panel);

    fab.addEventListener('click', () => {
      panel.hidden = !panel.hidden;
      if (!panel.hidden) renderPanel();
    });
    panel.addEventListener('click', onPanelClick);
    panel.addEventListener('change', onPanelChange);
  }

  function tierRow(t, i) {
    return el('tr', null,
      el('td', null, el('input', { type: 'number', class: 'tmsh-min', min: 0, step: 'any', value: t.min })),
      el('td', null, el('input', { type: 'color', class: 'tmsh-color', value: t.color })),
      el('td', null, el('input', { type: 'text', class: 'tmsh-label', maxlength: MAX_LABEL, placeholder: 'label', value: t.label })),
      el('td', null, el('button', { type: 'button', 'data-act': 'del', 'data-i': i, title: 'Remove tier' }, '✕')),
    );
  }

  function checkbox(id, checked, text) {
    return el('label', { class: 'tmsh-check' }, el('input', { type: 'checkbox', id, checked }), text);
  }

  function renderPanel(status) {
    const tiers = S[tierKey(S.mode)];
    const mode = el('select', { id: 'tmsh-mode' },
      el('option', { value: 'abs' }, 'profit per unit ($)'),
      el('option', { value: 'pct' }, 'margin (% of market price)'),
    );
    mode.value = S.mode;

    panel.dataset.mode = S.mode;
    panel.replaceChildren(
      el('h3', null, 'Shop Sell Price Highlighter'),
      el('label', null, 'Compare by ', mode),
      el('table', null,
        el('tr', null, el('th', null, S.mode === 'pct' ? 'Min %' : 'Min $'), el('th', null, 'Colour'), el('th', null, 'Label'), el('th')),
        ...tiers.map(tierRow),
      ),
      el('button', { type: 'button', 'data-act': 'add' }, '+ Add tier'),
      el('div', { style: 'margin-top:10px' },
        checkbox('tmsh-inline', S.inlineLabel, 'Show profit next to the price'),
        checkbox('tmsh-total', S.showTotal, 'Include listing total (profit × quantity)'),
        checkbox('tmsh-hide', S.hideUnprofitable, 'Hide unprofitable listings'),
        checkbox('tmsh-summary', S.showSummary, 'Show count badge on the gear button'),
      ),
      el('div', { class: 'tmsh-row' },
        el('button', { type: 'button', class: 'tmsh-primary', 'data-act': 'save' }, 'Save'),
        el('button', { type: 'button', 'data-act': 'reset' }, 'Reset to defaults'),
        el('button', { type: 'button', 'data-act': 'close' }, 'Close'),
      ),
      el('div', { class: 'tmsh-status' }, status || ''),
      el('div', { class: 'tmsh-muted' },
        `Shop prices generated ${SHOP_PRICES_GENERATED || 'unknown'} (${Object.keys(SHOP_SELL_PRICES).length} items). `,
        `Settings are stored only on this device (${storage.backend}).`,
      ),
    );
  }

  // Read the panel's current inputs into S (in memory, not yet saved).
  function syncFromPanel() {
    const tiers = [];
    for (const tr of panel.querySelectorAll('tr')) {
      const min = tr.querySelector('.tmsh-min');
      if (!min) continue;
      tiers.push({
        min: Number(min.value),
        color: tr.querySelector('.tmsh-color').value,
        label: tr.querySelector('.tmsh-label').value.trim(),
      });
    }
    // tiers belong to the mode the panel was rendered with, not the (possibly just changed) select
    S[tierKey(panel.dataset.mode)] = tiers.filter((t) => Number.isFinite(t.min));
    S.inlineLabel = panel.querySelector('#tmsh-inline').checked;
    S.showTotal = panel.querySelector('#tmsh-total').checked;
    S.hideUnprofitable = panel.querySelector('#tmsh-hide').checked;
    S.showSummary = panel.querySelector('#tmsh-summary').checked;
    S.mode = panel.querySelector('#tmsh-mode').value === 'pct' ? 'pct' : 'abs';
  }

  function onPanelChange(e) {
    if (e.target.id === 'tmsh-mode') {
      syncFromPanel();
      renderPanel();
    }
  }

  async function onPanelClick(e) {
    const btn = e.target.closest('button[data-act]');
    if (!btn) return;
    const act = btn.dataset.act;

    if (act === 'add') {
      syncFromPanel();
      S[tierKey(S.mode)].push({ min: 0, color: '#ffffff', label: '' });
      renderPanel();
    } else if (act === 'del') {
      syncFromPanel();
      S[tierKey(S.mode)].splice(Number(btn.dataset.i), 1);
      renderPanel();
    } else if (act === 'save') {
      syncFromPanel();
      S = normalizeSettings(S);
      const ok = await storage.save(S);
      rescan();
      if (ok) panel.hidden = true;
      else renderPanel('Could not save settings (storage full or unavailable).');
    } else if (act === 'reset') {
      await storage.clear();
      S = normalizeSettings(null);
      rescan();
      renderPanel();
    } else if (act === 'close') {
      panel.hidden = true;
    }
  }

  // ---------------------------------------------------------------- boot
  async function boot() {
    if (!Object.keys(SHOP_SELL_PRICES).length) {
      console.warn(TAG, 'SHOP_SELL_PRICES is empty - run build-prices.ps1 first');
      return;
    }
    S = normalizeSettings(await storage.load());
    log('loaded prices', Object.keys(SHOP_SELL_PRICES).length, 'via', storage.backend, 'settings', S);

    buildUI();
    scan();

    let timer = null;
    const scheduleScan = (mutations) => {
      // ignore mutations caused by our own panel
      if (mutations && mutations.every((m) => panel.contains(m.target))) return;
      clearTimeout(timer);
      timer = setTimeout(scan, 150);
    };
    new MutationObserver(scheduleScan).observe(document.body, {
      childList: true, subtree: true, characterData: true,
    });
    window.addEventListener('hashchange', () => scheduleScan());
  }

  boot().catch((err) => console.error(TAG, 'failed to start', err));
})();
